SourceCode.Declaration:
[
    DataContractAttribute
]
public class AVAUnblockProdTableWorkContract
{
    List    recIdList;
    boolean initFromRecord;

}

Method.Source:
[
    DataMemberAttribute,
    AifCollectionTypeAttribute(identifierStr(@return), Types::Int64),
    AifCollectionTypeAttribute(identifierStr(_recIdLIst), Types::Int64),
    SysOperationControlVisibilityAttribute(false)
]
public List parmRecIdList(List _recIdLIst = recIdList)
{
    recIdLIst = _recIdList;

    return recIdList;
}

[
    DataMemberAttribute,
    SysOperationControlVisibilityAttribute(false)
]
public boolean parmInitFromRecord(boolean _initFromRecord = initFromRecord)
{
    initFromRecord = _initFromRecord;

    return initFromRecord;
}

public void initFromArgs(Args _args)
{
    MultiSelectionContext   multiSelectionContext;
    ProdTable               prodTable;
    List                    recIds;

    multiSelectionContext   = _args.multiSelectionContext();
    recIds                  = new List(Types::Int64);

    if (multiSelectionContext)
    {
        prodTable     = multiSelectionContext.getFirst();

        if (!prodTable)
        {
            prodTable = _args.record();
        }

        do
        {
            recIds.addEnd(prodTable.RecId);

            prodTable = multiSelectionContext.getNext();
        }
        while (prodTable);
    }
    else
    {
        throw error(Error::missingRecord(funcName()));
    }

    this.parmRecIdList(recIds);
}
